insert into public.services (id, slug, title, summary, description, icon, deliverables, price_from_cents, duration_label, booking_deposit_cents, featured, sort_order) values
  ('00000000-0000-4000-8000-002100000001', 'starting-your-business', 'Starting your business', 'Turn an idea into a registered, structured business with a clear first-year plan.', 'For women at the very beginning. We help you test the idea, choose the right business structure, register it properly and set out the first steps.', 'lightbulb', array['Idea and customer check', 'Registration guidance', 'First-year action plan'], null, null, 0, true, 1),
  ('00000000-0000-4000-8000-002100000002', 'operations', 'Operations', 'Simple systems for how work gets done, so the business runs without chaos.', 'We look at how you deliver your product or service, where time and money leak out, and set up routines and tools that fit your size.', 'settings', array['Process review', 'Simple systems and checklists', 'Compliance check'], null, null, 0, true, 2),
  ('00000000-0000-4000-8000-002100000003', 'marketing', 'Marketing', 'Find the right customers and reach them without a big budget.', 'We help you understand who buys from you and why, shape your message, and choose the few marketing channels worth your time.', 'target', array['Customer profile', 'Message and offer', 'Low-cost marketing plan'], null, null, 0, true, 3),
  ('00000000-0000-4000-8000-002100000004', 'finance', 'Finance', 'Understand your numbers, price for profit and get ready for funding.', 'We help you separate business and personal money, keep simple records, price properly and prepare the documents funders ask for.', 'trending-up', array['Record-keeping set-up', 'Pricing review', 'Funding readiness'], null, null, 0, true, 4)
insert into public.live_sessions (id, slug, title, summary, description, presenter, starts_at, duration_minutes, platform, price_cents, capacity, sort_order, published) values
  ('00000000-0000-4000-8000-002200000001', 'business-clinic-marketing', 'Business Clinic: Marketing on a Small Budget', 'A live session on finding customers without spending much, with time for your own questions.', 'We cover the free and low-cost ways to reach customers: WhatsApp Business, Google Business Profile, referrals and simple social media routines.
insert into public.live_session_links (session_id, join_url) values
  ('00000000-0000-4000-8000-002200000001', ''),
  ('00000000-0000-4000-8000-002200000002', '')
insert into public.toolkit_articles (id, category, slug, title, summary, reading_minutes, featured, sort_order, blocks, published) values
  ('00000000-0000-4000-8000-002300000001', 'operations', 'register-your-business', 'Register your business and stay compliant', 'The registrations a new South African business needs, and the ones that come later.', 6, true, 1, '[{"type":"text","markdown":"Registering properly makes your business real in the eyes of customers, banks and funders. Most of it can be done online."},{"type":"slide","title":"Start with these"},{"type":"text","markdown":"- **Register a company with CIPC.** A private company (Pty) Ltd keeps your personal assets separate from the business.\n- **Open a business bank account** in the company''s name.\n- **Register with SARS** for income tax. New companies are usually registered automatically when CIPC registration is done; confirm this on SARS eFiling."},{"type":"slide","title":"When the business grows"},{"type":"text","markdown":"- **VAT** becomes compulsory once your turnover passes the threshold set by SARS. Check sars.gov.za for the current amount.\n- **UIF and PAYE** apply as soon as you employ someone.\n- **B-BBEE**: a small business can usually confirm its status with a sworn affidavit, which many corporate and government buyers ask for."},{"type":"callout","tone":"important","title":"Protect personal information","text":"If you keep customer names, numbers or ID details, the Protection of Personal Information Act (POPIA) applies. Keep only what you need and store it safely."},{"type":"exercise","title":"Your next step","text":"Write down which of the registrations above you already have, and the date you will complete the next one."}]'::jsonb, true),
  ('00000000-0000-4000-8000-002300000002', 'operations', 'simple-systems', 'Simple systems that save you time', 'Write down how the work gets done, so it gets done the same way every time.', 5, false, 2, '[{"type":"text","markdown":"A system is simply the way a task is done, written down. Systems let you serve more customers without working longer hours, and let someone else help you."},{"type":"slide","title":"The five processes every business has"},{"type":"text","markdown":"1. **Getting customers**: how people hear about you and ask to buy.\n2. **Delivering**: making the product or providing the service.\n3. **Getting paid**: quotes, invoices and following up.\n4. **Paying others**: suppliers, rent, staff.\n5. **Admin**: records, compliance and planning."},{"type":"callout","tone":"tip","title":"Start small","text":"A one-page checklist for each process is enough. Improve it each time something goes wrong."},{"type":"exercise","title":"Your next step","text":"Choose the process that causes you the most stress and write its steps as a checklist this week."}]'::jsonb, true),
  ('00000000-0000-4000-8000-002300000003', 'marketing', 'know-your-customer', 'Know your customer before you market', 'Marketing works when you know exactly who you are talking to.', 5, true, 1, '[{"type":"text","markdown":"Trying to sell to everyone usually means selling to no one. Start by describing the one customer you most want to serve."},{"type":"slide","title":"Describe your customer"},{"type":"text","markdown":"- Who is she or he? Age, location, work, family.\n- What problem do they have that you solve?\n- Where do they spend time, online and in person?\n- What makes them trust a business enough to buy?"},{"type":"slide","title":"Turn it into a message"},{"type":"text","markdown":"Write one sentence: *I help [customer] to [result] without [the thing they worry about].* Use it on your social media, flyers and when you introduce yourself."},{"type":"exercise","title":"Your next step","text":"Speak to three real customers this week. Ask why they bought from you and write down their exact words."}]'::jsonb, true),
  ('00000000-0000-4000-8000-002300000004', 'marketing', 'marketing-on-a-small-budget', 'Marketing on a small budget', 'Free and low-cost ways to reach customers in your area and online.', 6, false, 2, '[{"type":"text","markdown":"You do not need a big budget to be seen. You need consistency."},{"type":"slide","title":"Free tools worth setting up"},{"type":"text","markdown":"- **WhatsApp Business**: a business profile, catalogue and quick replies.\n- **Google Business Profile**: shows your business on Google Maps and search.\n- **One social media platform** where your customers already are. Post on it every week."},{"type":"slide","title":"Word of mouth"},{"type":"text","markdown":"Happy customers are your best marketing. Ask for a review after every sale, and thank people who refer others to you."},{"type":"exercise","title":"Your next step","text":"Set up one free tool from the list above and ask three customers for a review."}]'::jsonb, true),
  ('00000000-0000-4000-8000-002300000005', 'finance', 'separate-business-and-personal-money', 'Separate your business and personal money', 'The first money habit every business needs, and how to pay yourself.', 5, true, 1, '[{"type":"text","markdown":"When business and personal money share one account, you cannot tell whether the business is making a profit. Separating them is the first step to growing."},{"type":"slide","title":"Three habits"},{"type":"text","markdown":"1. **Use a business bank account** for every business payment in and out.\n2. **Pay yourself a fixed amount** each month instead of taking money when you need it.\n3. **Keep every slip and invoice**, even as photos on your phone."},{"type":"callout","tone":"tip","title":"Why funders care","text":"Banks and funders ask for bank statements. A clean business account shows them your business is real and well run."},{"type":"exercise","title":"Your next step","text":"Decide on the fixed amount you will pay yourself each month and write it down."}]'::jsonb, true),
  ('00000000-0000-4000-8000-002300000006', 'finance', 'price-for-profit', 'Price for profit', 'Know your costs, then set a price that pays you and grows the business.', 6, false, 2, '[{"type":"text","markdown":"Many businesses are busy but not profitable, because the price does not cover all the costs. Pricing starts with knowing your costs."},{"type":"slide","title":"Work out your costs"},{"type":"text","markdown":"- **Direct costs**: materials and anything spent on each item or job.\n- **Running costs**: rent, data, transport, your own salary, spread across the month.\n- **Profit**: the amount left to grow the business. It is not optional."},{"type":"slide","title":"A simple formula"},{"type":"text","markdown":"Price = direct cost per item + share of running costs per item + profit. Then compare with what customers pay elsewhere, and explain clearly why yours is worth it."},{"type":"exercise","title":"Your next step","text":"Work out the full cost of your best-selling product or service. Is your price covering it?"}]'::jsonb, true)
